-- Generated by the pinned official Supabase CLI. Individual owner approval only.
-- No cron, worker grant, provider call, update/delete writer or automatic retries.
alter table tracker_private.google_calendar_connections add column authorization_generation uuid not null default gen_random_uuid();
create table tracker_private.calendar_write_commands (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references public.tracker_members(user_id),
  target_kind text not null check(target_kind in ('occurrence','milestone')),
  target_id uuid not null,
  fingerprint text not null check(fingerprint ~ '^[a-f0-9]{64}$'),
  connection_generation uuid not null,
  provider_event_id text not null unique check(length(provider_event_id) between 5 and 1024 and provider_event_id ~ '^[0-9a-v]+$'),
  payload jsonb not null check(jsonb_typeof(payload)='object'),
  approved_snapshot jsonb not null check(jsonb_typeof(approved_snapshot)='object'),
  state text not null default 'pending' check(state in ('pending','processing','succeeded','uncertain','failed')),
  approved_at timestamptz not null default clock_timestamp(),
  updated_at timestamptz not null default clock_timestamp(),
  lease_token uuid,
  lease_until timestamptz,
  attempts integer not null default 0 check(attempts>=0),
  retry_not_before timestamptz,
  last_error text check(last_error ~ '^[a-z][a-z0-9_]{0,63}$'),
  unique(owner_id,target_kind,target_id),
  check((lease_token is null)=(lease_until is null)),
  check((state='processing')=(lease_token is not null))
);
alter table tracker_private.calendar_write_commands enable row level security;
create policy owner_calendar_commands on tracker_private.calendar_write_commands for select to authenticated
  using(owner_id=(select auth.uid()) and public.is_tracker_member());
revoke all on tracker_private.calendar_write_commands from public,anon,authenticated,service_role;
create function tracker_private.keep_calendar_approval_immutable() returns trigger language plpgsql set search_path='' as $$
begin
  if row(new.id,new.owner_id,new.target_kind,new.target_id,new.fingerprint,new.connection_generation,new.provider_event_id,new.payload,new.approved_snapshot,new.approved_at)
    is distinct from row(old.id,old.owner_id,old.target_kind,old.target_id,old.fingerprint,old.connection_generation,old.provider_event_id,old.payload,old.approved_snapshot,old.approved_at) then
    raise exception 'Approved calendar payload is immutable' using errcode='23000';
  end if;
  return new;
end $$;
revoke all on function tracker_private.keep_calendar_approval_immutable() from public,anon,authenticated,service_role;
create trigger immutable_calendar_approval before update on tracker_private.calendar_write_commands
  for each row execute function tracker_private.keep_calendar_approval_immutable();

-- Definers live outside the exposed schema; public wrappers are invokers.
create function tracker_private.calendar_command_json(c tracker_private.calendar_write_commands) returns jsonb
language sql stable set search_path='' as $$
  select jsonb_build_object('id',c.id,'kind',c.target_kind,'targetId',c.target_id,'state',c.state,
    'providerEventId',c.provider_event_id,'payload',c.payload,'approvedAt',c.approved_at,'lastError',c.last_error,'retryNotBefore',c.retry_not_before,'connectionGeneration',c.connection_generation);
$$;
revoke all on function tracker_private.calendar_command_json(tracker_private.calendar_write_commands) from public,anon,authenticated,service_role;

create function tracker_private.calendar_write_preview(p_kind text,p_target_id uuid) returns jsonb
language plpgsql security definer set search_path='' set timezone='UTC' as $$
declare o public.opportunities; oc public.occurrences; m public.milestones; s public.sources;
  v_facts jsonb; v_preview jsonb; v_extra jsonb; v_existing tracker_private.calendar_write_commands; v_blocked text;
  v_connection tracker_private.google_calendar_connections; v_title text; v_description text;
begin
  if auth.uid() is null or not public.is_tracker_member() then raise exception 'Not authorized' using errcode='42501'; end if;
  if p_kind is null or p_kind not in ('occurrence','milestone') or p_target_id is null then raise exception 'Invalid calendar target' using errcode='22023'; end if;
  if p_kind='occurrence' then
    select * into oc from public.occurrences where id=p_target_id and owner_id=auth.uid();
    if not found then raise exception 'Calendar target unavailable' using errcode='42501'; end if;
    select * into o from public.opportunities where id=oc.opportunity_id and owner_id=auth.uid();
    v_facts:=jsonb_build_object('opportunity',to_jsonb(o),'target',to_jsonb(oc));
    v_blocked:=case when oc.status<>'scheduled' then 'not_scheduled'
      when oc.all_day or oc.date_precision<>'instant' or oc.starts_at is null or oc.ends_at is null or oc.ends_at<=oc.starts_at then 'unknown_interval'
      when oc.starts_at<=clock_timestamp() then 'event_started' else null end;
    v_preview:=jsonb_build_object('location',oc.location,'startsAt',oc.starts_at,'endsAt',oc.ends_at,
      'sourceLocalText',oc.local_start_text,'timezone',oc.timezone,'uncertainties',o.uncertainties,
      'canApprove',v_blocked is null,'blockedReason',v_blocked);
  else
    select * into m from public.milestones where id=p_target_id and owner_id=auth.uid();
    if not found then raise exception 'Calendar target unavailable' using errcode='42501'; end if;
    select * into o from public.opportunities where id=m.opportunity_id and owner_id=auth.uid();
    select facts into v_extra from public.entity_versions where milestone_id=m.id and owner_id=auth.uid() and content_sha256=m.content_sha256;
    v_facts:=jsonb_build_object('opportunity',to_jsonb(o),'target',to_jsonb(m),'versionFacts',v_extra);
    v_preview:=jsonb_build_object('location',null,'startsAt',m.occurs_at,'endsAt',null,
      'sourceLocalText',coalesce(v_extra->>'source_local_text',m.occurs_on::text),'timezone',v_extra->>'timezone',
      'uncertainties',o.uncertainties || case when m.uncertainty is null then '[]'::jsonb else jsonb_build_array(m.uncertainty) end,
      'canApprove',true,'blockedReason',null,'milestoneKind',m.kind,'actionUrl',m.action_url);
  end if;
  if o.id is null then raise exception 'Calendar target unavailable' using errcode='42501'; end if;
  select * into s from public.sources where id=o.source_id and owner_id=auth.uid();
  select * into v_connection from tracker_private.google_calendar_connections where owner_id=auth.uid();
  select * into v_existing from tracker_private.calendar_write_commands where owner_id=auth.uid() and target_kind=p_kind and target_id=p_target_id;
  v_title:=case when p_kind='milestone' then 'Reminder: ' else '' end||o.title;
  v_description:='Source: '||o.source_url||E'\nAdded after explicit approval in opptrack. Ticket availability unverified.';
  if length(v_title)>1010 or length(v_description)>10000 or length(v_preview->>'location')>2000 then
    v_preview:=v_preview||jsonb_build_object('canApprove',false,'blockedReason','payload_too_long');
  end if;
  v_facts:=v_facts||jsonb_build_object('calendarBlueprint',jsonb_build_object(
    'summary',v_title,'description',v_description,
    'timeZone','America/New_York','useDefaultReminders',false,'version',1),
    'connectionGeneration',v_connection.authorization_generation,'connectionScope',v_connection.scope);
  return v_preview || jsonb_build_object('kind',p_kind,'targetId',p_target_id,'title',o.title,'description',o.description,
    'calendarTitle',v_title,'calendarDescription',v_description,'connectionGeneration',v_connection.authorization_generation,
    'sourceUrl',o.source_url,'sourceHealth',s.health_status,'lastSuccessAt',s.last_success_at,'cadenceSeconds',s.cadence_seconds,
    'fingerprint',pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(v_facts::text,'UTF8')),'hex'),
    'existingCommand',case when v_existing.id is null then null else tracker_private.calendar_command_json(v_existing) end);
end $$;

create function tracker_private.calendar_write_approve(p_kind text,p_target_id uuid,p_expected_fingerprint text,p_start_at timestamptz,p_end_at timestamptz) returns jsonb
language plpgsql security definer set search_path='' set timezone='UTC' as $$
declare v_preview jsonb; v_command tracker_private.calendar_write_commands; v_id uuid:=gen_random_uuid();
  v_start timestamptz; v_end timestamptz; v_payload jsonb; v_parent uuid; v_connection tracker_private.google_calendar_connections;
begin
  if auth.uid() is null or not public.is_tracker_member() then raise exception 'Not authorized' using errcode='42501'; end if;
  if p_kind is null or p_kind not in ('occurrence','milestone') or p_target_id is null then raise exception 'Invalid calendar target' using errcode='22023'; end if;
  select * into v_connection from tracker_private.google_calendar_connections where owner_id=auth.uid() for share;
  if not found or v_connection.scope<>'https://www.googleapis.com/auth/calendar.events.owned' then raise exception 'Reconnect Calendar with owner-approved writing' using errcode='42501'; end if;
  -- Serialize duplicate approvals before locks/fingerprint validation, with one durable identity.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(auth.uid()::text||':'||p_kind||':'||p_target_id::text,0));
  select * into v_command from tracker_private.calendar_write_commands where owner_id=auth.uid() and target_kind=p_kind and target_id=p_target_id for update;
  if found then
    if v_command.connection_generation<>v_connection.authorization_generation then raise exception 'Calendar authorization changed; this approval cannot be sent to a different connection' using errcode='40001'; end if;
    if p_kind='milestone' and (p_start_at is distinct from (v_command.payload->'start'->>'dateTime')::timestamptz or p_end_at is distinct from (v_command.payload->'end'->>'dateTime')::timestamptz) then
      raise exception 'This target already has a different approved reminder' using errcode='40001';
    end if;
    return tracker_private.calendar_command_json(v_command);
  end if;
  -- Parent first matches ingestion's lock order. Reparenting is rejected below.
  if p_kind='occurrence' then select opportunity_id into v_parent from public.occurrences where id=p_target_id and owner_id=auth.uid();
  else select opportunity_id into v_parent from public.milestones where id=p_target_id and owner_id=auth.uid(); end if;
  perform 1 from public.opportunities where id=v_parent and owner_id=auth.uid() for update;
  if p_kind='occurrence' then perform 1 from public.occurrences where id=p_target_id and owner_id=auth.uid() and opportunity_id=v_parent for update;
  else perform 1 from public.milestones where id=p_target_id and owner_id=auth.uid() and opportunity_id=v_parent for update; end if;
  if not found then raise exception 'Calendar target changed or unavailable' using errcode='40001'; end if;
  v_preview:=tracker_private.calendar_write_preview(p_kind,p_target_id);
  if p_expected_fingerprint is null or v_preview->>'fingerprint'<>p_expected_fingerprint then raise exception 'Calendar facts changed; review again' using errcode='40001'; end if;
  if v_preview->>'sourceUrl' is null or (v_preview->>'sourceUrl') !~ '^https://[^[:space:]<>]+$' then raise exception 'A safe HTTPS source URL is required' using errcode='22023'; end if;
  if v_preview->>'blockedReason'='payload_too_long' then raise exception 'Calendar fields exceed supported lengths' using errcode='22023'; end if;
  if p_kind='occurrence' then
    if not (v_preview->>'canApprove')::boolean then raise exception 'A future scheduled occurrence with a verified start and end is required' using errcode='22023'; end if;
    if p_start_at is not null or p_end_at is not null then raise exception 'Occurrence times cannot be overridden' using errcode='22023'; end if;
    v_start:=(v_preview->>'startsAt')::timestamptz; v_end:=(v_preview->>'endsAt')::timestamptz;
  else
    if p_start_at is null or p_end_at is null or not isfinite(p_start_at) or not isfinite(p_end_at)
      or p_start_at<=clock_timestamp() or p_end_at<=p_start_at or p_end_at>p_start_at+interval '24 hours' then
      raise exception 'Choose a future reminder start and end, at most 24 hours apart' using errcode='22023';
    end if;
    v_start:=p_start_at; v_end:=p_end_at;
  end if;
  if not isfinite(v_start) or not isfinite(v_end) then raise exception 'Finite calendar times required' using errcode='22023'; end if;
  -- The source URL is plain text; untrusted source HTML is never sent to Google.
  v_payload:=jsonb_build_object('summary',v_preview->>'calendarTitle',
    'description',v_preview->>'calendarDescription',
    'start',jsonb_build_object('dateTime',v_start,'timeZone','America/New_York'),
    'end',jsonb_build_object('dateTime',v_end,'timeZone','America/New_York'),
    'reminders',jsonb_build_object('useDefault',false),
    'extendedProperties',jsonb_build_object('private',jsonb_build_object('opptrackCommandId',v_id,'opptrackFingerprint',v_preview->>'fingerprint')));
  if p_kind='occurrence' and nullif(v_preview->>'location','') is not null then v_payload:=v_payload||jsonb_build_object('location',v_preview->>'location'); end if;
  insert into tracker_private.calendar_write_commands(id,owner_id,target_kind,target_id,fingerprint,connection_generation,provider_event_id,payload,approved_snapshot)
    values(v_id,auth.uid(),p_kind,p_target_id,v_preview->>'fingerprint',v_connection.authorization_generation,
      'opp'||pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(auth.uid()::text||':'||p_kind||':'||p_target_id::text,'UTF8')),'hex'),v_payload,v_preview-'existingCommand') returning * into v_command;
  return tracker_private.calendar_command_json(v_command);
end $$;

create function tracker_private.calendar_write_get(p_id uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare c tracker_private.calendar_write_commands;
begin
  if auth.uid() is null or not public.is_tracker_member() then raise exception 'Not authorized' using errcode='42501'; end if;
  select * into c from tracker_private.calendar_write_commands where id=p_id and owner_id=auth.uid();
  if not found then return null; end if;
  return tracker_private.calendar_command_json(c);
end $$;
create function tracker_private.calendar_write_list() returns jsonb
language plpgsql stable security definer set search_path='' as $$
begin
  if auth.uid() is null or not public.is_tracker_member() then raise exception 'Not authorized' using errcode='42501'; end if;
  return coalesce((select jsonb_agg(tracker_private.calendar_command_json(c) order by c.approved_at desc,c.id) from tracker_private.calendar_write_commands c where c.owner_id=auth.uid()),'[]'::jsonb);
end $$;
create function tracker_private.calendar_write_claim(p_id uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare c tracker_private.calendar_write_commands; v_now timestamptz:=clock_timestamp(); v_connection tracker_private.google_calendar_connections;
begin
  if auth.uid() is null or not public.is_tracker_member() then raise exception 'Not authorized' using errcode='42501'; end if;
  select * into c from tracker_private.calendar_write_commands where id=p_id and owner_id=auth.uid() for update;
  if not found then raise exception 'Calendar command unavailable' using errcode='42501'; end if;
  select * into v_connection from tracker_private.google_calendar_connections where owner_id=auth.uid() for share;
  if not found or v_connection.scope<>'https://www.googleapis.com/auth/calendar.events.owned' then raise exception 'Reconnect Calendar with owner-approved writing' using errcode='42501'; end if;
  if c.connection_generation<>v_connection.authorization_generation then raise exception 'Calendar authorization changed; this approval cannot be sent to a different connection' using errcode='40001'; end if;
  if c.state='succeeded' or (c.state='processing' and c.lease_until>v_now) or c.retry_not_before>v_now then return tracker_private.calendar_command_json(c); end if;
  update tracker_private.calendar_write_commands set state='processing',lease_token=gen_random_uuid(),lease_until=v_now+interval '60 seconds',attempts=attempts+1,updated_at=v_now
    where id=c.id returning * into c;
  return tracker_private.calendar_command_json(c)||jsonb_build_object('leaseToken',c.lease_token);
end $$;
create function tracker_private.calendar_write_finish(p_id uuid,p_lease_token uuid,p_state text,p_error_code text,p_retry_after_seconds integer) returns jsonb
language plpgsql security definer set search_path='' as $$
declare c tracker_private.calendar_write_commands;
begin
  if auth.uid() is null or not public.is_tracker_member() then raise exception 'Not authorized' using errcode='42501'; end if;
  if p_retry_after_seconds is null or p_retry_after_seconds not between 0 and 86400 or p_state is null or p_state not in ('succeeded','uncertain','failed') or (p_error_code is not null and p_error_code !~ '^[a-z][a-z0-9_]{0,63}$')
    or (p_state='succeeded' and p_error_code is not null) then raise exception 'Invalid command result' using errcode='22023'; end if;
  update tracker_private.calendar_write_commands set state=p_state,last_error=p_error_code,lease_token=null,lease_until=null,updated_at=clock_timestamp(),retry_not_before=case when p_state<>'succeeded' and p_retry_after_seconds>0 then clock_timestamp()+make_interval(secs=>p_retry_after_seconds) else null end
    where id=p_id and owner_id=auth.uid() and state='processing' and lease_token=p_lease_token and lease_until>clock_timestamp() returning * into c;
  if not found then raise exception 'Calendar command lease changed or expired' using errcode='40001'; end if;
  return tracker_private.calendar_command_json(c);
end $$;

create function public.calendar_write_preview(p_kind text,p_target_id uuid) returns jsonb language sql security invoker set search_path='' as $$ select tracker_private.calendar_write_preview(p_kind,p_target_id); $$;
create function public.calendar_write_approve(p_kind text,p_target_id uuid,p_expected_fingerprint text,p_start_at timestamptz default null,p_end_at timestamptz default null) returns jsonb language sql security invoker set search_path='' as $$ select tracker_private.calendar_write_approve(p_kind,p_target_id,p_expected_fingerprint,p_start_at,p_end_at); $$;
create function public.calendar_write_get(p_id uuid) returns jsonb language sql stable security invoker set search_path='' as $$ select tracker_private.calendar_write_get(p_id); $$;
create function public.calendar_write_list() returns jsonb language sql stable security invoker set search_path='' as $$ select tracker_private.calendar_write_list(); $$;
create function public.calendar_write_claim(p_id uuid) returns jsonb language sql security invoker set search_path='' as $$ select tracker_private.calendar_write_claim(p_id); $$;
create function public.calendar_write_finish(p_id uuid,p_lease_token uuid,p_state text,p_error_code text default null,p_retry_after_seconds integer default 0) returns jsonb language sql security invoker set search_path='' as $$ select tracker_private.calendar_write_finish(p_id,p_lease_token,p_state,p_error_code,p_retry_after_seconds); $$;
do $$ declare f record; begin
  for f in select p.oid::regprocedure as signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','tracker_private') and p.proname in ('calendar_write_preview','calendar_write_approve','calendar_write_get','calendar_write_list','calendar_write_claim','calendar_write_finish') loop
    execute format('revoke all on function %s from public,anon,authenticated,service_role',f.signature);
    execute format('grant execute on function %s to authenticated',f.signature);
  end loop;
end $$;
grant usage on schema tracker_private to authenticated;

-- Existing read-only grants continue to work. Scope elevation is a separate RPC,
-- called only after the owner has consented to Google's owned-event scope.
alter table tracker_private.google_calendar_connections drop constraint google_calendar_connections_scope_check;
alter table tracker_private.google_calendar_connections add constraint google_calendar_connections_scope_check
  check(scope in ('https://www.googleapis.com/auth/calendar.events.readonly','https://www.googleapis.com/auth/calendar.events.owned'));
create function tracker_private.calendar_connection_put_scoped(p_encrypted_credentials text,p_expected_revision uuid,p_scope text,p_new_authorization boolean) returns uuid
language plpgsql security definer set search_path='' as $$
declare v_revision uuid;
begin
  if auth.uid() is null or not public.is_tracker_member() then raise exception 'Not authorized' using errcode='42501'; end if;
  if p_scope is null or p_scope not in ('https://www.googleapis.com/auth/calendar.events.readonly','https://www.googleapis.com/auth/calendar.events.owned') or p_new_authorization is null then raise exception 'Unsupported calendar scope' using errcode='22023'; end if;
  if p_expected_revision is null then
    insert into tracker_private.google_calendar_connections(owner_id,encrypted_credentials,scope) values(auth.uid(),p_encrypted_credentials,p_scope)
      on conflict(owner_id) do nothing returning revision into v_revision;
  else
    update tracker_private.google_calendar_connections set encrypted_credentials=p_encrypted_credentials,scope=p_scope,revision=gen_random_uuid(),updated_at=now(),authorization_generation=case when p_new_authorization then gen_random_uuid() else authorization_generation end
      where owner_id=auth.uid() and revision=p_expected_revision returning revision into v_revision;
  end if;
  if v_revision is null then raise exception 'Calendar connection changed' using errcode='40001'; end if;
  return v_revision;
end $$;
create function public.calendar_connection_put_scoped(p_encrypted_credentials text,p_expected_revision uuid,p_scope text,p_new_authorization boolean default false) returns uuid
language sql security invoker set search_path='' as $$ select tracker_private.calendar_connection_put_scoped(p_encrypted_credentials,p_expected_revision,p_scope,p_new_authorization); $$;
revoke all on function tracker_private.calendar_connection_put_scoped(text,uuid,text,boolean),public.calendar_connection_put_scoped(text,uuid,text,boolean) from public,anon,authenticated,service_role;
grant execute on function tracker_private.calendar_connection_put_scoped(text,uuid,text,boolean),public.calendar_connection_put_scoped(text,uuid,text,boolean) to authenticated;
create or replace function public.calendar_connection_put(p_encrypted_credentials text,p_expected_revision uuid default null) returns uuid
language sql security invoker set search_path='' as $$ select tracker_private.calendar_connection_put_scoped(p_encrypted_credentials,p_expected_revision,'https://www.googleapis.com/auth/calendar.events.readonly',false); $$;
create or replace function public.calendar_connection_get() returns jsonb
language plpgsql stable security definer set search_path='' as $$
begin
  if auth.uid() is null or not public.is_tracker_member() then raise exception 'Not authorized' using errcode='42501'; end if;
  return(select jsonb_build_object('encrypted_credentials',c.encrypted_credentials,'scope',c.scope,'revision',c.revision,'connected_at',c.connected_at,'updated_at',c.updated_at,'authorization_generation',c.authorization_generation) from tracker_private.google_calendar_connections c where c.owner_id=auth.uid());
end $$;
